def check_k(k):
    count = 0
    start = 10**(k-1)
    end = 10**k
    digits = {0, 1, 2, 8}
    for n in range(start, end):
        if n % 3 == 0:
            if all(int(d) in digits for d in str(n)):
                count += 1
    return count

for k in range(1, 5):
    print(f"k={k}, count={check_k(k)}")

